        <input type="email" @bind="Model.Email" @bind:event="onchange" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Model.Phone" @bind:event="onchange" />
    </div>

    <div class="form-group">
