@page "/apply"
@using sv_154796f690ed4eb49cbe5997cdae5fa7.Components.Pages.Apply
@using sv_154796f690ed4eb49cbe5997cdae5fa7.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo" ValidateEmail="ApplicationService.ValidateEmailAsync" OnNext="NextStep" />
