@page "/apply"
@using sv_154796f690ed4eb49cbe5997cdae5fa7.Components.Pages.Apply
@using sv_154796f690ed4eb49cbe5997cdae5fa7.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo" ValidateEmail="ApplicationService.ValidateEmailAsync" OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="references" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep @bind-CoverLetterText="coverLetter" OnNext="NextStep" OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep @ref="reviewStepRef"
                        Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="PreviousStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();
    private ReviewStep? reviewStepRef;

    private PersonalInfoStep.PersonalInfoModel personalInfo = new();
    private List<WorkEntryForm.WorkEntryModel> workEntries = new() { new() };
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };
    private string coverLetter = "";

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task SubmitApplication()
    {
        try
        {
            var application = new JobApplication(
                new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            var appId = await ApplicationService.SubmitApplicationAsync(application);
            reviewStepRef?.SetSubmitted(appId);
        }
        catch (Exception ex)
        {
            reviewStepRef?.SetError($"Submission failed: {ex.Message}");
        }
    }
}

